# Fixes two problems with the buyer-facing share button on the listing
# sheet:
#
# 1. On a PC (mouse), tapping the share button just nudged the sheet up
#    and down instead of sharing anything. Root cause: the button sits
#    inside the same draggable header area used to expand/collapse the
#    sheet, and a click there was being picked up by that drag logic as a
#    "tap the handle" gesture (toggling half/full height) before the
#    button's own click ever got a chance to do anything. This is now
#    fixed by stopping that gesture from starting at all when a click
#    begins on the share/favorite buttons specifically.
#
# 2. On desktop, even once that's fixed, some browsers technically support
#    the same native-share API used on phones, but calling it first can
#    silently block the Facebook popup fallback if it then fails (a known
#    browser quirk: the popup no longer looks like a direct result of the
#    click by that point). Desktop (mouse/trackpad) now skips straight to
#    the reliable Facebook popup instead of risking that.
#
# Changed: components/ListingSheet.js, components/ShareButton.js. No
# database changes, no new dependency. Uses the same exact-bytes approach
# as the last fix (not raw text) so this can't suffer the character
# corruption bug from before. Safe to re-run if something fails partway
# through.

$projectPath = "C:\Users\Bastian\Documents\WebDesign\SaleHop-app\salehopproject\salehop"

Write-Host "Moving into $projectPath ..." -ForegroundColor Cyan
if (-not (Test-Path $projectPath)) {
    Write-Host "ERROR: That folder doesn't exist. Double-check the path and edit it at the top of this script." -ForegroundColor Red
    exit 1
}
Set-Location $projectPath

if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
    Write-Host "ERROR: git isn't installed (or not on PATH)." -ForegroundColor Red
    exit 1
}

New-Item -ItemType Directory -Force -Path "components" | Out-Null

Write-Host "Writing components\ShareButton.js ..." -ForegroundColor Cyan
$b64 = ""
$bytes = [Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes("components\ShareButton.js", $bytes)

Write-Host "Writing components\ListingSheet.js ..." -ForegroundColor Cyan
$b64 = ""
$bytes = [Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes("components\ListingSheet.js", $bytes)

Write-Host "Staging, committing, and pushing ..." -ForegroundColor Cyan
git add .
git commit -m "Fix share button being swallowed by the drag gesture on desktop, and skip Web Share API on non-touch devices"

if ($LASTEXITCODE -ne 0) {
    Write-Host ""
    Write-Host "If that failed with 'Please tell me who you are', run these two lines (with your info) then re-run this script:" -ForegroundColor Yellow
    Write-Host '  git config --global user.email "you@example.com"' -ForegroundColor Yellow
    Write-Host '  git config --global user.name "Your Name"' -ForegroundColor Yellow
    exit 1
}

git push

if ($LASTEXITCODE -eq 0) {
    Write-Host ""
    Write-Host "Done! Once Vercel finishes deploying, try the share button again from your PC -- it should pop open the Facebook share window instead of just nudging the sheet." -ForegroundColor Green
} else {
    Write-Host ""
    Write-Host "The push didn't finish cleanly -- scroll up for git's error message and send it to me." -ForegroundColor Red
}
